class Solution {
    public int smallestIndex(int[] nums) {
        for (int i = 0; i < nums.length; i++) {
            int s = 0;
            for (char c : String.valueOf(nums[i]).toCharArray()) s += c - '0';
            if (s == i) return i;
        }
        return -1;
    }
}

